import{z as B,x as A,o as e,c as p,q as l,j as n,D as r,d as s,s as E,S as o,b as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Chaitin–Briggs","description":"","frontmatter":{"title":"Chaitin–Briggs","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chaitin-briggs.md","filePath":"cs/chaitin-briggs.md","lastUpdated":1791063341000}'),g={name:"cs/chaitin-briggs.md"};function d(h,a,m,C,c,u){const t=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=l('<h1 id="chaitin–briggs" tabindex="-1">Chaitin–Briggs <a class="header-anchor" href="#chaitin–briggs" aria-label="Permalink to &quot;Chaitin–Briggs&quot;">​</a></h1><div class="epigraph"><p>冲突图上简化低度数节点，溢出时乐观着色：Briggs 允许度数 ≥K 的点仍试着着色，减少不必要 spill。</p><footer>—— 据 Chaitin et al., 1981；Briggs, Cooper and Torczon, Improvements to Graph Coloring Register Allocation, 1994；龙书整理</footer></div><p>上一课<a href="/cs/linear-scan-regalloc">线性扫描</a>用区间。主干着色课已给冲突图。缺口是 <strong>Chaitin–Briggs 启发式</strong>：简化、合并、溢出选择、乐观着色。本课钉迭代，不写合并细节——下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>K 着色 NP。<span class="marginnote">冲突图（interference graph）可以这样读：每个节点是一个临时变量，两个节点之间有边，意思是「这两个变量的存活期重叠，不能共用同一个寄存器」。着色就是给图上相邻节点分配不同的颜色——颜色即寄存器编号。</span>Chaitin：反复去掉 \\(deg\\lt K\\) 的点压栈<span class="marginnote">数字实例：在 x86-64 上可自由分配的通用寄存器大约 15 个左右（还要扣掉 rsp、rbp 这类有专职的），所以 \\(K\\approx 15\\)。一个节点的度数若小于 15，说明与它冲突的变量不超过 14 个，它弹栈时必然能挑到一个邻居没用过的寄存器。</span>，剩下高度数当溢出候选，插入 spill 后重建图。Briggs：压栈时对 \\(deg\\ge K\\) 也压，弹出时再试着色，成功则免一次 spill。<span class="marginnote">初学者容易以为「度数 ≥ K 就必须溢出」——那是 Chaitin 的悲观策略。Briggs 的观察是：度数只统计了邻居个数，没考虑邻居之间会互相撞色，弹栈时邻居实际用掉的颜色往往少于 \\(K\\) 种，所以高 degree 也常常能着色成功。</span>缺口是<strong>这套栈机</strong>，不是线性扫描的区间表。</p><p>SSA 冲突图是弦图，可多项式着色——点名；析构后一般不是。</p><h3 id="乐观不是「忽略冲突」" tabindex="-1">乐观不是「忽略冲突」 <a class="header-anchor" href="#乐观不是「忽略冲突」" aria-label="Permalink to &quot;乐观不是「忽略冲突」&quot;">​</a></h3><p>弹出时仍检查邻居颜色；失败才真溢出。不是随便同色。</p><p><span class="marginnote">Chaitin 1981/82。Briggs 1994 TOPLAS。George–Appel 迭代合并。本课 Briggs 乐观为核心增量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建图。可选保守合并。简化循环。选溢出代价（循环深度、use 密度）。重写 spill，迭代直到可着色。弹出着色。</p>',11)),(e(),n(o,null,{default:r(()=>[E(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IG%5B%22%E5%86%B2%E7%AA%81%E5%9B%BE%22%5D%20--%3E%20SIM%5B%22%E7%AE%80%E5%8C%96%20%2F%20%E4%B9%90%E8%A7%82%E5%8E%8B%E6%A0%88%22%5D%0A%20%20SIM%20--%3E%20SP%5B%22%E6%BA%A2%E5%87%BA%E9%87%8D%E5%86%99%22%5D%0A%20%20SP%20--%3E%20IG%0A%20%20SIM%20--%3E%20COL%5B%22%E5%BC%B9%E5%87%BA%E7%9D%80%E8%89%B2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("p",null,"与调用约定：预着色节点（物理寄存器约束）固定颜色，图更大。",-1)),a[4]||(a[4]=i("h2",{id:"机制",tabindex:"-1"},[s("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=i("p",null,"凝聚：无限迭代要防。代价模型错会溢出热区间。不要在 JIT 热路径上跑多次全图重建——这是 AOT 更常见。",-1)),a[6]||(a[6]=i("p",null,"与线性扫描：同一函数可比较 spill 数，作为编译器质量指标。",-1)),a[7]||(a[7]=i("p",null,"弹栈阶段「乐观」到底赌的是什么，可以拆成一条判定链：",-1)),(e(),n(o,null,{default:r(()=>[E(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20POP%5B%22%E4%BB%8E%E6%A0%88%E9%A1%B6%E5%BC%B9%E5%87%BA%E4%B8%80%E4%B8%AA%E8%8A%82%E7%82%B9%22%5D%20--%3E%20NB%5B%22%E6%9F%A5%E7%9C%8B%E5%B7%B2%E7%9D%80%E8%89%B2%E9%82%BB%E5%B1%85%E7%94%A8%E6%8E%89%E7%9A%84%E9%A2%9C%E8%89%B2%22%5D%0A%20%20NB%20--%3E%20FREE%7B%22%E8%BF%98%E5%AD%98%E5%9C%A8%E6%9C%AA%E5%8D%A0%E7%94%A8%E7%9A%84%E9%A2%9C%E8%89%B2%3F%22%7D%0A%20%20FREE%20--%20%22%E6%9C%89%22%20--%3E%20OK%5B%22%E5%88%86%E9%85%8D%E8%AF%A5%E9%A2%9C%E8%89%B2%22%5D%0A%20%20FREE%20--%20%22%E6%B2%A1%E6%9C%89%22%20--%3E%20REAL%5B%22%E7%9C%9F%E6%AD%A3%E6%BA%A2%E5%87%BA%3A%20%E6%8F%92%E5%85%A5%E5%AD%98%E5%8F%96%E6%8C%87%E4%BB%A4%22%5D%0A%20%20REAL%20--%3E%20RW%5B%22%E9%87%8D%E5%86%99%E4%BB%A3%E7%A0%81%E5%B9%B6%E9%87%8D%E5%BB%BA%E5%86%B2%E7%AA%81%E5%9B%BE%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 George–Appel。后课默认：AOT 可用 Briggs 着色。下一课合并与拆分：对付拷贝与长区间。<span class="marginnote">「溢出」（spill）就是把寄存器里装不下的变量赶到栈内存上：每次用到它都要先 load 进寄存器、用完再 store 回去。直觉类比：寄存器是办公桌，栈是储物柜——桌子放不下的文件进柜子，但每次要看一眼都得跑一趟柜子，慢。</span></p><p>也不把图着色当地图四色课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Chaitin 简化+溢出；Briggs 乐观少 spill。</li><li>预着色尊重 ABI。</li><li>SSA 上弦图是特例。</li><li>出处：Chaitin et al.；Briggs, Cooper and Torczon, 1994；龙书。</li></ul>',5))])}const b=B(g,[["render",d]]);export{f as __pageData,b as default};
